pub(super) fn format_max(value: f32) -> String {
    if value == f32::MAX {
        "unbounded".to_string()
    } else {
        format_number(value)
    }
}

pub(super) fn format_number(value: f32) -> String {
    if !value.is_finite() {
        return value.to_string();
    }

    let mut text = format!("{value:.2}");
    while text.contains('.') && text.ends_with('0') {
        text.pop();
    }
    if text.ends_with('.') {
        text.pop();
    }
    if text == "-0" { "0".to_string() } else { text }
}
